            // The tool of the capture: no arguments, as its schema says.
            req.tools = vec![ToolDef::new(
                "get_current_time",
                "Return the current server time. Takes no arguments.",
                json!({
                    "type": "object",
                    "properties": {},
                    "required": [],
                    "additionalProperties": false
                }),
            )];
        }
        req
    }

